   void nodeActions(Storage.Node n){String[] actions={"Open","Open containing folder","Copy","Move","Rename","Delete","Properties / checksums","Open as text","Open as hex","Add / remove favorite","Create archive / ISO","APK / DEX workshop","Open archive with password"};boolean extractable=archiveCanExtract(n);if(extractable){actions=Arrays.copyOf(actions,actions.length+1);actions[actions.length-1]=archiveExtractLabel(n);}final int extractIndex=13;items(n.name,actions,i->{if(extractable&&i==extractIndex){String extension=ext(n.name);if(extension.equals("zip")||extension.equals("7z"))input("Archive password","Leave blank if none","",password->extractArchiveNode(n,password));else extractArchiveNode(n,"");return;}switch(i){case 0:open(n);break;case 1:reveal(n);break;case 2:case 3:clipboard=new ArrayList<>(Collections.singletonList(n));clipboardMove=i==3;updateActionRailState();toast("Choose a destination, then Paste");break;case 4:renameNode(n);break;case 5:delete(Collections.singletonList(n));break;case 6:properties(n);break;case 7:edit(n,false);break;case 8:edit(n,true);break;case 9:toggleBookmark(n);break;case 10:createArchive(Collections.singletonList(n));break;case 11:workshop(n);break;case 12:input("Archive password","Password","",p->browseArchive(n,p));break;}});}
  boolean archiveCanExtract(Storage.Node n){return !n.dir&&Arrays.asList("zip","7z","rar","tar","gz","bz2","xz","lzma","iso","cpio","ar","apk","jar","aab","apks","xapk").contains(ext(n.name));}
 String archiveExtractLabel(Storage.Node n){String extension=ext(n.name);return extension.equals("zip")?"Unzip to folder":extension.equals("rar")?"Unrar to folder":"Extract to folder";}
 void delete(List<Storage.Node> nodes){confirm("Delete permanently?",nodes.size()+" selected items and their contents will be removed. This cannot be undone.",()->job("Deleting",()->{for(Storage.Node n:nodes){if(cancel.get())throw new InterruptedIOException();storage.delete(n);}panes[active].selected.clear();return "Deleted";}));}
 void properties(Storage.Node n){job("Reading properties",()->{String text=n.name+"\n\n"+n.path+"\n\n"+(n.dir?"Directory":size(n.size))+"\nModified "+date(n.modified);if(!n.dir)try(InputStream in=storage.read(n)){text+="\n\n"+BinaryTools.hashes(in);}String result=text;ui.post(()->textDialog("Properties",result));return "Properties ready";});}
