  void binaryFileMenu(Storage.Node n){items(n.name,new String[]{"View as hex","Open with a compatible app"},i->{if(i==0){edit(n,true);return;}job("Opening binary file",()->{File f=stage(n);ui.post(()->whenIdle(()->externalChooser(f)));return "Ready to open";});});}
  void externalChooser(File f){Uri uri=ShareProvider.uri(f);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/octet-stream").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(intent,"Open binary with"));}catch(ActivityNotFoundException e){textDialog("No compatible app found","Install an app that supports this binary format, then try again.");}}
  void external(File f){Uri uri=ShareProvider.uri(f);String ext=ext(f.getName()),mime=ext.equals("apk")?"application/vnd.android.package-archive":MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);if(mime==null)mime="application/octet-stream";Intent i=new Intent(ext.equals("apk")?Intent.ACTION_INSTALL_PACKAGE:Intent.ACTION_VIEW).setDataAndType(uri,mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(i);}catch(ActivityNotFoundException e){textDialog("Could not open installer","Android could not open this package. Check that the APK is valid and that installs from File Xplorer are allowed.");}}
 void installApk(Storage.Node n){
  String type=ext(n.name);if(!type.equals("apk")&&!type.equals("xapk")){toast("Choose an APK or XAPK file");return;}
  if(Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){confirm("Allow APK installs","Android will open its install permission for File Xplorer. Return here and tap the APK or XAPK again.",()->startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName()))));return;}
  job("Preparing Android installer",()->{
   File source=stage(n),folder=new File(getCacheDir(),"install-"+UUID.randomUUID());if(!folder.mkdirs())throw new IOException("Could not prepare package staging.");
   List<File> apks=new ArrayList<>(),obbs=new ArrayList<>();String packageName;
   if(type.equals("apk")){
    PackageInfo info=getPackageManager().getPackageArchiveInfo(source.getAbsolutePath(),0);if(info==null||info.packageName==null)throw new IOException("Android could not read this APK.");
    packageName=info.packageName;File base=new File(folder,"base.apk");Files.copy(source.toPath(),base.toPath(),StandardCopyOption.REPLACE_EXISTING);apks.add(base);
   }else{
    XapkArchive.Payload payload=XapkArchive.extract(source,folder,cancel,(bytes,name)->progress(bytes,name));obbs.addAll(payload.obbs);
    String foundPackage=null;File base=null;List<File> splits=new ArrayList<>();
    for(File candidate:payload.apks){
     PackageInfo info=getPackageManager().getPackageArchiveInfo(candidate.getAbsolutePath(),0);if(info==null||info.packageName==null)throw new IOException("Could not read XAPK package "+candidate.getName());
     if(foundPackage==null)foundPackage=info.packageName;else if(!foundPackage.equals(info.packageName))throw new IOException("The XAPK contains APKs from different packages.");
     String split=info.splitNames!=null&&info.splitNames.length>0?info.splitNames[0]:null;
     if(split==null){if(base!=null)throw new IOException("The XAPK contains more than one base APK.");base=new File(folder,"base.apk");Files.copy(candidate.toPath(),base.toPath(),StandardCopyOption.REPLACE_EXISTING);}
     else{Storage.validName(split);File target=new File(folder,split+".apk");if(target.exists())throw new IOException("The XAPK contains duplicate split APK names.");Files.copy(candidate.toPath(),target.toPath());splits.add(target);}
    }
    if(base==null||foundPackage==null)throw new IOException("The XAPK is missing a valid base APK.");
    packageName=foundPackage;apks.add(base);splits.sort(Comparator.comparing(File::getName,String.CASE_INSENSITIVE_ORDER));apks.addAll(splits);
   }
   final String targetPackage=packageName;final List<File> expansionFiles=new ArrayList<>(obbs);
   PackageInstallFlow.install(this,apks,targetPackage,ui,new PackageInstallFlow.Listener(){
    public void onSubmitted(){toast("Android’s installer is ready. Confirm the installation there.");}
    public void onFinished(boolean success,String message){toast(success&&!expansionFiles.isEmpty()?message+" · XAPK expansion files were not installed by File Xplorer.":message);}
   });
   return "Package installation submitted";
  });
 }
 String ext(String name){int dot=name.lastIndexOf('.');return dot>=0?name.substring(dot+1).toLowerCase(Locale.ROOT):"";}
  File stage(Storage.Node n)throws IOException{if(!n.saf()&&!n.ftp())return new File(n.path);if(n.dir)throw new IOException("Select a file");if(n.size>getCacheDir().getUsableSpace()-32L*1024*1024)throw new IOException("Not enough temporary space to process this provider file");File folder=new File(getCacheDir(),"stage-"+UUID.randomUUID());if(!folder.mkdir())throw new IOException("Cannot prepare staging folder");File out=new File(folder,n.name);try(InputStream in=storage.read(n);OutputStream to=new FileOutputStream(out)){byte[] b=new byte[65536];int k;while((k=in.read(b))!=-1){if(cancel.get())throw new InterruptedIOException("Cancelled");to.write(b,0,k);progress(k,n.name);}}return out;}
 File exportSources(List<Storage.Node> nodes)throws IOException{File dir=new File(getCacheDir(),"sources-"+UUID.randomUUID());if(!dir.mkdir())throw new IOException("Cannot prepare sources");Storage.Node dest=storage.node(dir,false);for(Storage.Node n:nodes)storage.copy(n,dest,cancel,(b,s)->progress(b,s));return dir;}
  void browseArchive(Storage.Node node,String password){job("Reading archive",()->{File f=stage(node);List<Archives.Entry> entries=Archives.list(f,password,cancel);ui.post(()->showArchive(node,f,password,entries));return entries.size()+" entries";});}
  void extractArchiveNode(Storage.Node node,String password){job("Preparing archive",()->{File f=stage(node);ui.post(()->whenIdle(()->extractArchive(node,f,password)));return "Archive ready";});}
  void showArchive(Storage.Node original,File f,String password,List<Archives.Entry> entries){ListView list=new ListView(this);String[] names=new String[entries.size()];for(int i=0;i<names.length;i++){Archives.Entry e=entries.get(i);names[i]=(e.directory?"▸ ":"")+e.name+"\n"+(e.directory?"Directory":size(e.size));}list.setAdapter(GlassDialog.adapter(this,names));AlertDialog dialog=new GlassDialog.Builder(this).setTitle(original.name+" · "+entries.size()+" entries").setView(list).setNegativeButton("Close",null).setPositiveButton(archiveExtractLabel(original),(a,b)->extractArchive(original,f,password)).setNeutralButton("Actions",(a,b)->archiveActions(original,f,password)).create();list.setOnItemClickListener((a,v,i,id)->{Archives.Entry e=entries.get(i);if(e.directory){toast("Folder: "+e.name);return;}job("Opening archive entry",()->{File dir=new File(getCacheDir(),"entry-"+UUID.randomUUID());dir.mkdir();String base=new File(e.name.replace('\\','/')).getName();File out=new File(dir,base);Archives.readEntry(f,e.name,out,password,cancel);ui.post(()->whenIdle(()->open(storage.node(out,false))));return "Entry ready";});});dialog.show();}
 void extractArchive(Storage.Node original,File file,String password){input("Extract into a new folder","Folder name",original.name.replaceFirst("\\.[^.]+$","")+"_extracted",name->{Storage.Node dest=panes[active].folder;job("Extracting archive",()->{if(localNode(dest)){File folder=new File(dest.path,name);Storage.validName(name);Archives.extract(file,folder,password,cancel);}else{File folder=new File(getCacheDir(),"extract-"+UUID.randomUUID());Archives.extract(file,folder,password,cancel);Storage.Node created=storage.create(dest,name,true);try{for(File child:Objects.requireNonNull(folder.listFiles()))storage.copy(storage.node(child,false),created,cancel,(b,s)->progress(b,s));}catch(IOException e){throw new IOException("Provider copy stopped. The partially extracted folder remains at "+name,e);}finally{storage.delete(storage.node(folder,false));}}return "Archive extracted";});});}
 void archiveActions(Storage.Node node,File archive,String password){items("Archive tools",new String[]{"Enter / change password","Test integrity","Add or replace file in ZIP","Delete entry from ZIP","APK workshop"},which->{if(which==0)input("Archive password","Password","",p->browseArchive(node,p));if(which==1)job("Testing archive",()->{Archives.verify(archive,password,cancel);return "Integrity checks passed";});if(which==2){if(!Archives.zip(archive)){toast("Entry replacement supports ZIP / APK / JAR");return;}input("Source file path","Absolute local file path","",source->input("ZIP entry name","Path inside archive",new File(source).getName(),entry->confirm("Modify archive?","A .bak copy is created first. APKs need signing after any modification.",()->job("Updating ZIP",()->{File f=new File(source);Files.copy(archive.toPath(),new File(archive+".bak").toPath(),StandardCopyOption.REPLACE_EXISTING);Archives.replaceZipEntry(archive,entry,f,password);writeBack(node,archive);return "Entry updated";}))));}if(which==3){if(!Archives.zip(archive)){toast("Entry deletion supports ZIP / APK / JAR");return;}input("Delete ZIP entry","Exact entry path","",entry->confirm("Delete archive entry?",entry,()->job("Updating ZIP",()->{Files.copy(archive.toPath(),new File(archive+".bak").toPath(),StandardCopyOption.REPLACE_EXISTING);Archives.removeZipEntry(archive,entry,password);writeBack(node,archive);return "Entry deleted";})));}if(which==4)workshop(node);});}
  void writeBack(Storage.Node n,File stage)throws IOException{if(!n.saf()&&!n.ftp()&&new File(n.path).equals(stage))return;try(InputStream in=new FileInputStream(stage);OutputStream out=storage.write(n)){FileSafety.transfer(in,out,Long.MAX_VALUE,cancel);}}
  void createArchive(List<Storage.Node> selected){String[] formats={"zip","7z","tar","tar.gz","tar.xz","tar.bz2","iso"};items("Create archive / disk image",new String[]{"ZIP · optional AES-256","7z · LZMA2","TAR","TAR + GZIP","TAR + XZ","TAR + BZIP2","ISO9660 + Joliet"},i->createArchive(selected,formats[i]));}
  void createArchive(List<Storage.Node> selected,String format){input("Output name","Archive file name","Archive."+format,name->{Value make=password->{Storage.Node dest=panes[active].folder;job("Creating "+format.toUpperCase(Locale.ROOT),()->{Storage.validName(name);List<File> sources=new ArrayList<>();boolean direct=selected.stream().allMatch(this::localNode);if(direct)for(Storage.Node n:selected)sources.add(new File(n.path));else {File staged=exportSources(selected);sources.addAll(Arrays.asList(Objects.requireNonNull(staged.listFiles())));}
       if(localNode(dest))Archives.create(new File(dest.path,name),sources,format,password,cancel);else{File temp=new File(getCacheDir(),"archive-"+UUID.randomUUID()+"."+format);Archives.create(temp,sources,format,password,cancel);Storage.Node out=storage.create(dest,name,false);try(InputStream in=new FileInputStream(temp);OutputStream to=storage.write(out)){FileSafety.transfer(in,to,Long.MAX_VALUE,cancel);}temp.delete();}return "Created "+name;});};if(format.equals("zip"))passwordDialog(make);else make.set("");});}
 void passwordDialog(Value action){LinearLayout l=col();pad(l,20);EditText e=field(l,"Optional password · leave empty for plain ZIP","");e.setInputType(129);new GlassDialog.Builder(this).setTitle("ZIP encryption").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Create",(a,b)->action.set(e.getText().toString())).show();}
 void edit(Storage.Node n,boolean hex){if(n.dir){toast("Choose a file");return;}job("Loading editor",()->{if(n.size>2*1024*1024)throw new IOException("This editor is limited to 2 MB. Use an external editor for larger files.");byte[] bytes;try(InputStream in=storage.read(n);ByteArrayOutputStream out=new ByteArrayOutputStream()){FileSafety.transfer(in,out,2*1024*1024,cancel);bytes=out.toByteArray();}ui.post(()->editor(n,bytes,hex));return "Editor ready";});}
 void editor(Storage.Node node,byte[] bytes,boolean hex){Dialog dialog=new GlassDialog.Editor(this);LinearLayout root=col();pad(root,14);root.setBackground(Visuals.glass(d(28),false));LinearLayout bar=row();bar.addView(heading(node.name+(hex?" · HEX":""),17),new LinearLayout.LayoutParams(0,d(48),1));bar.addView(textButton("Close",dialog::dismiss));root.addView(bar);Charset charset=bytes.length>=2&&((bytes[0]==(byte)0xff&&bytes[1]==(byte)0xfe)||(bytes[0]==(byte)0xfe&&bytes[1]==(byte)0xff))?StandardCharsets.UTF_16:StandardCharsets.UTF_8;
  EditText editor=new EditText(this);editor.setGravity(Gravity.TOP|Gravity.START);editor.setTypeface(android.graphics.Typeface.MONOSPACE);editor.setTextSize(hex?12:14);editor.setTextColor(Visuals.INK);editor.setBackground(Visuals.glass(d(20),false));editor.setPadding(d(14),d(14),d(14),d(14));editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);editor.setHorizontallyScrolling(false);if(hex){StringBuilder raw=new StringBuilder();for(int i=0;i<bytes.length;i++){raw.append(String.format("%02X ",bytes[i]));if(i%16==15)raw.append('\n');}editor.setText(raw);}else editor.setText(new String(bytes,charset));root.addView(editor,new LinearLayout.LayoutParams(-1,0,1));LinearLayout actions=row();actions.addView(textButton("Find / replace",()->findReplace(editor)));actions.addView(textButton("Save copy",()->input("Save a copy","File name",node.name+".edited",name->job("Saving copy",()->{byte[] data=hex?BinaryTools.unhex(editor.getText().toString()):editor.getText().toString().getBytes(charset);Storage.Node out=storage.create(panes[active].folder,name,false);try(OutputStream to=storage.write(out)){to.write(data);}return "Copy saved";}))));actions.addView(textButton("Save",()->{final String text=editor.getText().toString();confirm("Save changes?","A backup of the original is kept in the app's private cache.",()->job("Saving changes",()->{File backup=new File(getCacheDir(),"backup-"+System.currentTimeMillis()+"-"+node.name);try(InputStream in=storage.read(node);OutputStream out=new FileOutputStream(backup)){FileSafety.transfer(in,out,2L*1024*1024,cancel);}byte[] data=hex?BinaryTools.unhex(text):text.getBytes(charset);if(localNode(node)){File f=new File(node.path),temp=new File(f.getParentFile(),".fx-save-"+UUID.randomUUID());Files.write(temp.toPath(),data);try{Files.move(temp.toPath(),f.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING);}}else try(OutputStream out=storage.write(node)){out.write(data);}return "Saved · backup in cache";}));}));root.addView(actions);dialog.setContentView(root);dialog.show();dialog.getWindow().setLayout(-1,-1);}
 void findReplace(EditText editor){LinearLayout f=col();pad(f,20);EditText find=field(f,"Find",""),replace=field(f,"Replace with","");CheckBox regex=check(f,"Regular expression",false),caseSensitive=check(f,"Case sensitive",false);new GlassDialog.Builder(this).setTitle("Find / replace").setView(f).setNegativeButton("Cancel",null).setNeutralButton("Find next",(a,b)->{try{String q=find.getText().toString();com.google.re2j.Pattern p=com.google.re2j.Pattern.compile(regex.isChecked()?q:com.google.re2j.Pattern.quote(q),caseSensitive.isChecked()?0:com.google.re2j.Pattern.CASE_INSENSITIVE);com.google.re2j.Matcher m=p.matcher(new SearchEngine.Guarded(editor.getText().toString()));int start=Math.max(0,editor.getSelectionEnd());if(m.find(start)||m.find(0)){editor.requestFocus();editor.setSelection(m.start(),m.end());}else toast("No match");}catch(Exception e){error(e);}}).setPositiveButton("Replace all",(a,b)->{try{com.google.re2j.Pattern p=com.google.re2j.Pattern.compile(regex.isChecked()?find.getText().toString():com.google.re2j.Pattern.quote(find.getText().toString()),caseSensitive.isChecked()?0:com.google.re2j.Pattern.CASE_INSENSITIVE);String replacement=regex.isChecked()?replace.getText().toString():com.google.re2j.Matcher.quoteReplacement(replace.getText().toString());editor.setText(p.matcher(new SearchEngine.Guarded(editor.getText().toString())).replaceAll(replacement));}catch(Exception e){error(e);}}).show();}
 void workshop(Storage.Node n){String type=ext(n.name);items("APK / DEX workbench",new String[]{"APK details / signatures","Decode AndroidManifest.xml","DEX class / method index","Disassemble DEX → smali","Assemble selected folder → DEX","Sign APK with device key","Export installed apps","Install APK"},i->{if(i==7){installApk(n);return;}if(i==6){installedApps();return;}if(i==4){if(!n.dir){toast("Choose the folder containing smali files");return;}input("DEX output file","File name","classes-edited.dex",name->job("Assembling DEX",()->{File dir=localNode(n)?new File(n.path):exportSources(Collections.singletonList(n));if(!localNode(n))dir=new File(dir,n.name);File out=new File(getCacheDir(),"assembled-"+UUID.randomUUID()+".dex");ApkWorkshop.assemble(dir,out);deliver(out,panes[active].folder,name);return "DEX assembled";}));return;}
  if(i==5){if(!type.equals("apk")){toast("Select an APK file");return;}input("Signed APK name","Output name",n.name.replace(".apk","-signed.apk"),name->confirm("Sign with File-Xplorer key?","This uses a key generated in this app's Android Keystore. It is not the original publisher's key. Signing does not grant the original app's update identity.",()->job("Signing APK",()->{File in=stage(n),out=new File(getCacheDir(),UUID.randomUUID()+"-signed.apk");KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);String alias="file-xplorer-apk-signing";if(!ks.containsAlias(alias)){KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA","AndroidKeyStore");generator.initialize(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_SIGN|KeyProperties.PURPOSE_VERIFY).setKeySize(2048).setDigests(KeyProperties.DIGEST_SHA256,KeyProperties.DIGEST_SHA512).setSignaturePaddings(KeyProperties.SIGNATURE_PADDING_RSA_PKCS1,KeyProperties.SIGNATURE_PADDING_RSA_PSS).setCertificateSubject(new X500Principal("CN=File-Xplorer Device Key")).setCertificateSerialNumber(BigInteger.ONE).setCertificateNotAfter(new Date(System.currentTimeMillis()+10L*365*86400000)).build());generator.generateKeyPair();}ApkWorkshop.sign(in,out,(PrivateKey)ks.getKey(alias,null),(X509Certificate)ks.getCertificate(alias));deliver(out,panes[active].folder,name);return "APK signed";})));return;}
  job("Inspecting app",()->{File f=stage(n);if(i==0){PackageInfo info=getPackageManager().getPackageArchiveInfo(f.getPath(),PackageManager.GET_PERMISSIONS|PackageManager.GET_SIGNING_CERTIFICATES);String text=info==null?"No Android package metadata":info.packageName+"\nVersion "+info.versionName+"\n\nPermissions\n"+Arrays.toString(info.requestedPermissions);text+="\n\n"+ApkWorkshop.verify(f);String value=text;ui.post(()->textDialog("APK details",value));}
   if(i==1){File xml=new File(getCacheDir(),"manifest-"+UUID.randomUUID()+".xml");Archives.readEntry(f,"AndroidManifest.xml",xml,"",cancel);String decoded=BinaryTools.binaryXml(Files.readAllBytes(xml.toPath()));ui.post(()->textDialog("Manifest · read-only decoded view",decoded));}
   if(i==2||i==3){File dex=f;if(!type.equals("dex")){dex=new File(getCacheDir(),"classes-"+UUID.randomUUID()+".dex");Archives.readEntry(f,"classes.dex",dex,"",cancel);}if(i==2){String value=ApkWorkshop.dexInfo(dex);ui.post(()->textDialog("DEX index",value));}else{File folder=new File(getCacheDir(),"smali-"+UUID.randomUUID());ApkWorkshop.disassemble(dex,folder);storage.copy(storage.node(folder,false),panes[active].folder,cancel,(b,s)->progress(b,s));}}return "Workbench complete";});});}
