 void installedApps(){job("Reading installed apps",()->{List<ApplicationInfo> apps=getPackageManager().getInstalledApplications(0);apps.sort(Comparator.comparing(a->a.loadLabel(getPackageManager()).toString().toLowerCase(Locale.ROOT)));String[] labels=new String[apps.size()];for(int i=0;i<apps.size();i++)labels[i]=apps.get(i).loadLabel(getPackageManager())+"\n"+apps.get(i).packageName;ui.post(()->new GlassDialog.Builder(this).setTitle("Installed apps · export APK").setItems(labels,(a,index)->{ApplicationInfo app=apps.get(index);confirm("Export "+app.loadLabel(getPackageManager())+"?","Writes base APK and any split APKs to the active folder.",()->job("Exporting app",()->{Storage.Node out=storage.create(panes[active].folder,app.packageName+"-"+System.currentTimeMillis(),true);List<String> paths=new ArrayList<>();paths.add(app.sourceDir);if(app.splitSourceDirs!=null)paths.addAll(Arrays.asList(app.splitSourceDirs));for(String p:paths)storage.copy(storage.node(new File(p),false),out,cancel,(b,s)->progress(b,s));return "APK set exported";}));}).setNegativeButton("Close",null).show());return "App list ready";});}
