 void tool(LinearLayout c,String glyph,String title,String desc,Runnable action){LinearLayout box=glass(16);LinearLayout r=row();ImageView im=new ImageView(this);im.setImageDrawable(new Visuals.Icon(glyph,Visuals.BLUE));r.addView(im,new LinearLayout.LayoutParams(d(29),d(29)));LinearLayout text=col();text.setPadding(d(15),0,0,0);text.addView(heading(title,17));gap(text,4);text.addView(label(desc,12,Visuals.MUTED));r.addView(text,new LinearLayout.LayoutParams(0,-2,1));box.addView(r);Visuals.press(box);box.setOnClickListener(v->action.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,d(12));c.addView(box,lp);}
  void terminal(){LinearLayout box=col();pad(box,20);EditText command=field(box,"Command","pwd");box.addView(label("Runs within the app’s normal permission scope.",12,Visuals.MUTED));new GlassDialog.Builder(this).setTitle("Terminal").setView(box).setNegativeButton("Close",null).setPositiveButton("Run",(a,b)->{String cmd=command.getText().toString();job("Running command",()->{String result=runTerminalCommand(cmd);ui.post(()->textDialog("App-scope command",result));return "Command finished";});}).show();}
   String runTerminalCommand(String command)throws Exception{java.lang.Process process=new ProcessBuilder("sh","-c",command).redirectErrorStream(true).start();ByteArrayOutputStream output=new ByteArrayOutputStream();Thread reader=new Thread(()->{try(InputStream in=process.getInputStream()){byte[] buffer=new byte[4096];int count,total=0;while((count=in.read(buffer))!=-1){int keep=Math.min(count,65536-total);if(keep>0)output.write(buffer,0,keep);total+=count;}}catch(IOException ignored){}},"filexplorer-terminal-reader");reader.setDaemon(true);reader.start();if(!process.waitFor(30,TimeUnit.SECONDS)){process.destroyForcibly();reader.join(1000);throw new IOException("Command timed out after 30 seconds");}reader.join(1000);return "Exit "+process.exitValue()+"\n"+output.toString("UTF-8");}
  void settings(){ScrollView s=scrollBody();LinearLayout c=col();s.addView(c);gap(c,20);c.addView(heading("Make room for you.",30));gap(c,24);tool(c,"settings","Appearance",prefs.getString("appearance","system")+" · light and dark glass",this::appearanceMenu);CheckBox animations=check(c,"Smooth animations",Visuals.motion);animations.setOnCheckedChangeListener((b,v)->{Visuals.motion=v;prefs.edit().putBoolean("motion",v).apply();});CheckBox blur=check(c,"Blur glass backgrounds",Visuals.blur);blur.setOnCheckedChangeListener((b,v)->{Visuals.blur=v;prefs.edit().putBoolean("blur",v).apply();render();});gap(c,12);tool(c,"drive","Storage permissions",allAccess()?"All files access is granted":"Choose all-files access or a specific folder",this::grantStorage);tool(c,"folder","Add SD card / USB folder","Android document-provider access",this::pickTree);CheckBox hidden=check(c,"Show hidden files",showHidden);hidden.setOnCheckedChangeListener((v,value)->{showHidden=value;prefs.edit().putBoolean("hidden",value).apply();});gap(c,20);tool(c,"document","Clear search and recents","Keeps files and bookmarks intact",()->{recent.clear();history.clear();saveNodes("recent",recent);toast("History cleared");});tool(c,"archive","Clear temporary cache","Removes staged files and editor backups",()->confirm("Clear cache?","Editor backups and temporary archive previews will be removed.",()->job("Clearing cache",()->{File[] files=getCacheDir().listFiles();if(files!=null)for(File f:files)storage.delete(storage.node(f));return "Cache cleared";})));tool(c,"document","Open-source notices","Libraries and feature limits",()->{try(InputStream in=getAssets().open("notices.txt")){textDialog("Open-source notices",new String(readAll(in,128*1024),StandardCharsets.UTF_8));}catch(Exception e){error(e);}});}
 void applyAppearance(){String mode=prefs.getString("appearance","system");boolean system=(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;Visuals.configure(mode.equals("dark")||mode.equals("system")&&system,getResources().getConfiguration().screenWidthDp<840);Visuals.motion=prefs.getBoolean("motion",true);Visuals.blur=prefs.getBoolean("blur",true);}
