 void analysis(){Storage.Node base=panes[active].folder;job("Analyzing storage",()->{PriorityQueue<Storage.Node> largest=new PriorityQueue<>(Comparator.comparingLong(n->n.size));ArrayDeque<Storage.Node> queue=new ArrayDeque<>();queue.add(base);Set<String> visited=new HashSet<>();long total=0,count=0;while(!queue.isEmpty()){if(cancel.get())throw new InterruptedIOException();Storage.Node dir=queue.removeFirst();String key=dir.saf()?dir.path:new File(dir.path).getCanonicalPath();if(!visited.add(key))continue;List<Storage.Node> nodes;try{nodes=storage.list(dir);}catch(IOException e){continue;}for(Storage.Node n:nodes){if(n.dir){if(!n.saf()&&Files.isSymbolicLink(new File(n.path).toPath()))continue;queue.add(n);}else{count++;total+=n.size;largest.offer(n);if(largest.size()>50)largest.poll();}}}List<Storage.Node> list=new ArrayList<>(largest);list.sort((a,b)->Long.compare(b.size,a.size));StringBuilder text=new StringBuilder(count+" files · "+size(total)+"\n\nLargest files\n");for(Storage.Node n:list)text.append(size(n.size)).append("  ").append(n.name).append("\n").append(n.path).append("\n\n");ui.post(()->textDialog("Storage analysis",text.toString()));return "Analysis complete";});}
 void globalMenu(){items("File Xplorer",new String[]{"Install APK / XAPK","Add storage location","Go to path","New folder / file","Toggle hidden files","Bookmarks","Capabilities"},i->{if(i==0)chooseInstallFile();if(i==1)storageLocationMenu();if(i==2)pathDialog();if(i==3)newItem();if(i==4){showHidden=!showHidden;prefs.edit().putBoolean("hidden",showHidden).apply();render();}if(i==5){String[] names=new String[bookmarks.size()];for(int j=0;j<names.length;j++)names[j]=bookmarks.get(j).name;items("Favorites",names,j->go(bookmarks.get(j)));}if(i==6){page="tools";render();}});}
 void grantStorage(){try{if(Build.VERSION.SDK_INT>=30)startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName())));else requestPermissions(new String[]{Manifest.permission.READ_EXTERNAL_STORAGE,Manifest.permission.WRITE_EXTERNAL_STORAGE},77);}catch(Exception e){pickTree();}}
