 void ftpForm(boolean secure){LinearLayout form=col();pad(form,18);EditText host=field(form,"Server host or IP","");EditText port=field(form,"Port","21");port.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);EditText username=field(form,"Username","");EditText password=field(form,"Password","");password.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);TextView note=label(secure?"Explicit FTPS encrypts credentials and file transfers.":"Classic FTP sends credentials and file contents without encryption. Use only on a trusted network.",12,secure?Visuals.MUTED:0xffa13c32);note.setPadding(d(4),d(4),d(4),d(8));form.addView(note);AlertDialog dialog=new GlassDialog.Builder(this).setTitle(secure?"Connect with FTPS":"Connect with FTP").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Connect",(a,b)->{int value;try{value=Integer.parseInt(port.getText().toString().trim());}catch(Exception e){port.setError("Enter a port");return;}String h=host.getText().toString(),u=username.getText().toString(),p=password.getText().toString();if(!secure){confirm("Use unencrypted FTP?","Your password and file contents can be read by others on the network.",()->connectFtp(h,value,u,p,false));}else connectFtp(h,value,u,p,true);}).create();dialog.show();}
 void connectFtp(String host,int port,String username,String password,boolean secure){job(secure?"Connecting with FTPS":"Connecting with FTP",()->{String id=ftp.connect(host,port,username,password,secure);Storage.Node root=new Storage.Node(FtpSessions.nodePath(id,"/"),host.trim(),true,0,System.currentTimeMillis());ui.post(()->{trees.removeIf(n->n.path.startsWith("ftpfs://"+id));trees.add(root);go(root);});return secure?"FTPS connected; credentials remain in memory":"FTP connected; credentials remain in memory";});}
 void chooseInstallFile(){try{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/vnd.android.package-archive","application/zip","application/octet-stream"});startActivityForResult(intent,301);}catch(Exception error){error(error);}}
 void pickTree(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(i,300);}catch(Exception e){error(e);}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;try{Uri uri=data.getData();if(req==300){getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));Storage.Node n=storage.tree(uri);trees.removeIf(t->t.path.equals(n.path));trees.add(n);saveNodes("trees",trees);go(n);}else if(req==301){Storage.Node n=storage.document(uri);installApk(n);}}catch(Exception e){error(e);}}
 void remember(Storage.Node n){recent.removeIf(r->r.key().equals(n.key()));recent.add(0,n);if(recent.size()>40)recent.remove(recent.size()-1);saveNodes("recent",recent);}
  void saveNodes(String key,List<Storage.Node> list){org.json.JSONArray a=new org.json.JSONArray();for(Storage.Node n:list)try{if(n.ftp())continue;org.json.JSONObject o=new org.json.JSONObject();o.put("path",n.path);o.put("name",n.name);o.put("dir",n.dir);o.put("size",n.size);o.put("modified",n.modified);a.put(o);}catch(Exception ignored){}prefs.edit().putString(key,a.toString()).apply();}
  void loadNodes(String key,List<Storage.Node> list){try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString(key,"[]"));for(int i=0;i<a.length();i++){org.json.JSONObject n=a.getJSONObject(i);String path=n.getString("path");if(path.startsWith("ftpfs://")||n.optBoolean("root"))continue;list.add(new Storage.Node(path,n.getString("name"),n.getBoolean("dir"),n.optLong("size"),n.optLong("modified")));}}catch(Exception ignored){}}
 void whenIdle(Runnable action){if(isFinishing()||isDestroyed())return;if(busy)ui.postDelayed(()->whenIdle(action),80);else action.run();}
  void job(String title,Task task){if(busy){toast("Wait for the current operation to finish");return;}busy=true;cancel=new AtomicBoolean();lastProgress=0;progress=new GlassDialog.Progress(this);progress.setTitle(title);progress.setMessage("Working…");progress.setCancelable(false);progress.setButton(DialogInterface.BUTTON_NEGATIVE,"Cancel",(a,b)->cancel.set(true));progress.show();io.submit(()->{try{String result=task.run();ui.post(()->{toast(result);jobLog.add(title+" · "+result);if(jobLog.size()>100)jobLog.remove(0);});}catch(Exception e){ui.post(()->{jobLog.add(title+" · "+e.getMessage());error(e);});}finally{ui.post(()->{if(progress!=null)progress.dismiss();busy=false;if(page.equals("browse")){updateActionRailState();refresh();}});}});}
 void progress(long bytes,String name){long now=SystemClock.uptimeMillis();if(now-lastProgress>250){lastProgress=now;ui.post(()->{if(progress!=null)progress.setMessage("Processing "+name+"\nCancel stops at the next safe read/write step.");});}}
 static byte[] readAll(InputStream in,int limit)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Content exceeds viewer limit");out.write(b,0,n);}return out.toByteArray();}
