 TextView statusToast;void toast(String s){if(isFinishing()||isDestroyed()||backdrop==null)return;if(statusToast!=null&&statusToast.getParent() instanceof ViewGroup)((ViewGroup)statusToast.getParent()).removeView(statusToast);TextView note=label(s,13,Visuals.INK);statusToast=note;note.setMaxLines(4);note.setPadding(d(18),d(14),d(18),d(14));note.setBackground(Visuals.glass(d(23),true));note.setElevation(d(14));note.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);FrameLayout host=backdrop;FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);p.setMargins(d(24),0,d(24),d(wide?28:page.equals("browse")?156:90));host.addView(note,p);Visuals.enter(note);ui.postDelayed(()->{if(Visuals.animate())note.animate().alpha(0).translationY(d(8)).setDuration(160).withEndAction(()->host.removeView(note)).start();else host.removeView(note);},3200);}void error(Throwable e){new GlassDialog.Builder(this).setTitle("Operation could not finish").setMessage(e.getMessage()==null?e.toString():e.getMessage()).setPositiveButton("Close",null).show();}
